@module sonority  src=sonority.lua  loc=1104  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state; ratios/cents are tuning.lua's, the placement carries them  @ 4
  @invariant  convex in the displacements, so the sweep order and the start buy speed, not the answer  @ 416
  @contract  ties, window, strength, stiffness, start (per strand), free (strands that sweep)  @ 417
  @contract  → displacements minimising springCost + pullCost, held strands at their start  @ 418
  @contract  each swept displacement inside its own strand's window  @ 419
  @invariant  a round decides one slot, so the states it cuts between have placed equally many  @ 537
  @invariant  the first member to place anchors and those before it wait, so one anchor spells each  @ 538
  @invariant  every state ties every member it places; an untied one states nothing, charges none  @ 539
  @invariant  the reach is read against the spelling's own offset, not which member anchors  @ 540
  @contract  members; seat/window/mayWait per strand; moves, width, stiffness → Spellings, best first  @ 657
  @contract  a join is one move; one offset of the spelling seats every member inside its own window  @ 658
  @contract  the width is a width per waiting count; math.huge enumerates the spellings whole  @ 659
  @contract  a sonority no chain reaches and no wait defers has no spelling: the list is empty  @ 660
  @invariant  what has closed is carried, which is what retaking it a cursor later would charge  @ 1017
  @invariant  an answer's debts stand in onset order, as the walk opens them and closes them in it  @ 1020
  @contract  onsets, a spelling list per onset, seat and window per strand, strength, stiffness, cap  @ 1021
  @contract  → the cheapest Answer, every answer carried extended by every spelling of the onset  @ 1022
  @contract  the strands the onset sounds relax; the rest of an answer stands at the cents it carries  @ 1023
  @contract  a sonority holding a waiter is charged in its own onset's slot, as its members place  @ 1024
  @contract  answers agreeing to half a cent ahead and owing the same merge; the set is cut to cap  @ 1025
  @contract  the cut runs over two pools, the answers that owe and the answers that have paid  @ 1026
  @contract  nil where an onset has no spelling — a sonority the target can't reach refuses it  @ 1027

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 5
  @shape  Strand = { notes={ {ppq,pitch,endppq,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes, the releases and the class  @ 6
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, the last n struck and whatever else still sounds  @ 7
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 8
  @shape  Spring = { i=<strand>, j=<strand>, delta=<cents> }; the pair is pure where d[j] - d[i] = delta  @ 302
  @shape  Window = { below=<cents to the step below>, above=<cents to the step above> }  @ 344
  @shape  Ties = { [strand] = { other, other, .., count, delta=<the tie deltas summed> } }  @ 366
  @shape  State = { at={ [slot]=Placed }, components={ {slot,..},.. }, parts, key, waits, score, lo/hi=<the offsets left open> }  @ 505
  @shape  Placed = { coords=Coords, cents=<the pure position>, deviation=<from the seat>, component }  @ 506
  @shape  Spelling = { box=<what its components carry>, springs={Spring,..}, waiting={member,..}, placed={ [strand]={ coords=Coords, component } } }  @ 656
  @shape  Onset = { ppq, members={strand,..}, sounding={strand,..}, mayWait={[strand]=true,..} }  @ 693
  @shape  Answer = { choice={ spelling per onset }, springs={ Spring list per onset }, box, displacement, cost, closed=<what the shut onsets charge>, held={ Held,.. } }  @ 1018
  @shape  Held = { onset, placed={ [strand]={ coords=Coords, component } }, waiting={ [strand]=true }, box=<charged so far> }  @ 1019

# Imports
  @const util = 'util'  @ 10
  @const tuning = 'tuning'  @ 11

# Module-level constants
  @const sonority = {}  @ 12
  @const budget = 200000  @ 186
  @const PURE = 50  @ 323
  @const TOLERANCE, SWEEPS = 1e-4, 1000  @ 362
  @const DEFERRED = '?'  @ 501
  @const AUDIBLE = 0.5  @ 720
  @const WIDTH, CAP = 24, 4  @ 1077

# Private functions
  -- The box
  -- The strands
  -- The walk
  @fn strikesInOrder(strands)  @ 76-89
      -- Every strike, in onset order, lowest last — so a released chord leaves its
      -- bass to the sonority that follows (design/adaptive-tuning.md § The model).
  @fn sounding(strand, ppq)  @ 93-98
      -- Half-open, so a note released where the next is struck does not sound there,
      -- and a passage whose notes stop as the next begin reads as the last n struck.
  @fn promote(recent, strands, index)  @ 102-108
      -- The class holds one entry however many notes write it: a restrike moves its
      -- own entry to the front, and a second strand of the class takes the entry over.
  -- The objective
  -- The solve
  @fn schedule(strands, sonorities)  @ 156-182
      -- A strand is live from the onset it is chosen at to the last that reads it, both
      -- known before enumeration (§ Solving it), and listed in strand order for keying.
      @contract  strands, sonorities → per onset the strands born there, live there, and held from before  @ 155
  @fn assertAffordable(strands, plan)  @ 188-198
  @fn placementsAt(strands, born, strength)  @ 202-221
      -- Every combination of the shortlists of the strands born at an onset, with the
      -- pull each charges — the same against every state, so charged once here.
  @fn outranks(state, best, count, rankOf)  @ 226-234
      -- Cost, then the strands one by one, so an exact tie breaks deterministically rather than
      -- by table order (design/adaptive-tuning.md § What the solver takes).
      @contract  true iff `state` is the better of the two, the lower rank winning a tie  @ 225
  @fn byChoice(state, index)  @ 237-239
      -- Ranks a strand by the candidate index the solve chose for it.
  @fn keyOf(choice, list)  @ 241-245
  -- The springs
  -- The relaxation
  @fn settle(ties, displacement, window, strength, stiffness)  @ 405-414
      -- One strand's optimum with the rest held: its springs' seats averaged against the pull,
      -- charged over the half-window the seats point it toward (design/adaptive-springs.md § The model).
  -- The candidates
  @fn joinCoords(coords, move)  @ 440-448
      -- A join's coords: the host's plus the move's, a cancelled prime dropped so two chains
      -- arriving at one spelling key alike (design/adaptive-springs.md § The candidates).
  @fn rebase(coords, from, to)  @ 452-461
      -- Coords are differences, so reading a member in another frame is one vector shift: what
      -- stood at `from` stands at `to`, a cancelled prime dropped as joinCoords drops it.
  @fn reachOf(deviation, window)  @ 465-467
      -- No note leaves the step it was notated on, and a spelling is placed as a whole, at one
      -- offset from the seats, so 'deviation' states which offsets remain open (design/adaptive-springs.md § The candidates).
  @fn coordString(coords)  @ 470-476
      -- Coords in one order, so two tables holding the same exponents read alike.
  @fn tokenOf(placed)  @ 480-482
      -- What a state has made of a member: the coords it was spelled at, and the component it
      -- joined into, so a member in a component of its own reads apart from the same coords tied in.
  @fn joinCost(state, component, placed, stiffness)  @ 486-498
      -- What a join costs where it lands: the box its component widens by, and a spring against
      -- each member already there, both priced before any displacement moves (§ The candidates).
  @fn admit(reached, seen, state, slot, placed, stiffness, lo, hi)  @ 507-526
      -- Keyed before it is built, so a candidate repeating a spelling costs its coords and its
      -- key alone; the state it would have extended is copied only where the spelling is new.
  @fn byScore(a, b)  @ 530-533
      -- Score, then the spelling itself, so an exact tie breaks on the coords rather than on
      -- table order, as sonority.solveToPoints breaks its own.
  @fn beamOver(seat, window, free, moves, width, stiffness)  @ 541-597
      -- One round per member decides one slot: a move to a member already placed, or left waiting.
      -- Every road decides the same slots, so a differing order's duplicates collapse where they land.
  @fn chargeOf(members, seat, placed)  @ 603-635
      -- What coords and seats state about a set of members: a spring per pair of a component,
      -- tied in member order as sonority.springs ties them, and the box a component carries.
      @contract  members, seat per strand, coords and component per placed member → springs, box  @ 601
      @contract  a member the map lacks is one still waiting, which states nothing and is passed over  @ 602
  @fn spellingOf(state, members, seat)  @ 639-652
      -- The state read back as the sonority's own: its members' coords under the strands they
      -- name, whom it left waiting, and what those state charged as any set of placed members is.
  -- The terms
  -- The search
  @fn visibleAhead(onsets)  @ 724-741
      -- The strands a later onset names and the walk has already moved, in strand order: all a
      -- continuation can read, since what nothing ahead names is settled and what nothing behind has sounded stands at zero alike (design/adaptive-springs.md § The solve).
  @fn soundingRuns(onsets)  @ 746-756
      -- The same run read the other way: an onset's strands split into those a later onset sounds
      -- too, which the relaxation can still move, and those it sounded last, which have stopped.
      @contract  onsets → per onset the strands it leaves moving and the strands it closes  @ 745
  @fn openFrom(onsets)  @ 762-775
      -- A strand sounds over one run of onsets, so once the walk is past every strand an onset
      -- named, nothing it charges can move again: the onsets before the cursor are closed.
      @invariant  the cursor only advances, so a closed onset stays closed for the rest of the walk  @ 760
      @contract  onsets → per onset the earliest onset a strand sounding there is named at  @ 761
  @fn diffString(coords, from)  @ 779-793
      -- The difference of two coords read straight to its string: what coordString would read
      -- of the rebase, fused so a key costs no intermediate table.
  @fn placementKey(members, placed, waiting)  @ 798-825
      -- What a sonority has been spelled as, however the spelling was reached: each component
      -- read from its earliest member, as chargeOf reads it, and the members still waiting.
      @invariant  two placements under one key charge alike, so a wait reaching one is no second road  @ 797
  @fn offeredBy(onsets, spellings)  @ 829-840
      -- What each onset's beam returned, read as placements: the spellings a wait may not come
      -- back with, taken from what the beam kept rather than what its moves could have reached.
  @fn answerKey(displacement, ahead, onsets, held)  @ 845-859
      -- An answer under the whole of what a continuation can tell it by: its cents at the strands
      -- ahead in half-cents, and the deferrals it has yet to pay.
      @invariant  one strand list serves every answer of an onset, so its cents key by position  @ 844
  @fn complete(entry, members, spelling)  @ 865-909
      -- What a spelling makes of a sonority still waiting: a waiter it places takes coords in the
      -- held sonority's frame through a member the two share, and nothing where they share none.
      @invariant  a waiter reaching two components merges them, every member shifted into the one frame  @ 863
      @invariant  a waiter tied to no member states no interval there, so its completion fails  @ 864
  @fn heldBy(spelling, at)  @ 913-917
      -- The entry a spelling that defers opens: which onset owes it, what it placed, whom it
      -- left, and what it has been charged so far.
  @fn settledOnsets(answer, from, at)  @ 921-928
      -- The onsets behind the cursor an answer has settled: the open ones, less any a deferral
      -- still rewrites, so what every spelling of the next onset reads alike is tied once.
  @fn cutBar(cap)  @ 933-957
      -- Where a pool's cut now sits: the cost of its cap-th best distinct key, held in a
      -- bounded sorted list, a listed key replaced where it improved (§ The solve).
      @invariant  a key's cost in reached only improves, so a stale bar is only ever too high  @ 932
  @fn extend(answer, spelling, onsets, at, seat, window, strength, stiffness, offered, carried, from, since, moving, stopped, bars)  @ 964-1013
      -- One answer extended by one spelling: the springs and box it has paid, each sonority it
      -- still holds charged again for what this spelling places, the onset's own strands relaxed.
      @contract  carried: the Ties over what the answer has settled, which this spelling's start from  @ 961
      @contract  nil where a wait comes back with a placement its own sonority offered (§ The candidates)  @ 962
      @contract  nil where a wait lands tied to no member of the sonority that deferred it  @ 963

# Public API (sonority.*)
  @api sonority.score(coordSet)  @ 19-34
      -- The axes are gathered before any is measured, so an axis no member names doesn't reach
      -- back to 0; the spans are the octave-free lcm/gcd's coords, whose height tuning.height gives.
      @contract  coords[] → tuning.height of the coords of the set's octave-free lcm/gcd  @ 18
  @api sonority.strands(notes, classOf)  @ 42-70
      -- Notes of a class that overlap hold one tuning (§ The strand); the running
      -- release is half-open, so a note struck at a release starts another.
      @contract  notes, classOf → a Strand per class per run of overlapping notes, shortlists unfilled  @ 40
      @contract  grouped by ascending class, each in strike order, whatever order the notes arrive in  @ 41
  @api sonority.walk(strands, n)  @ 113-128
      -- The whole onset is absorbed before the sonority is taken, so a chord wider
      -- than n leaves its own lowest notes standing rather than its predecessor's.
      @contract  strands, n → a Sonority per onset: last n distinct classes struck, plus sounding  @ 112
  @api sonority.cost(strands, n, strength, choice)  @ 135-149
      -- The pull is counted once per strand rather than once per note, so an octave
      -- doubling changes no answer: the box already charges it nothing.
      @contract  strands, n, strength, choice → box over the walk + strength × strain² per strand  @ 134
  @api sonority.solveToPoints(strands, n, strength)  @ 251-296
      -- The state carries the whole choice vector rather than a backpointer: two
      -- generations are alive at a time and the budget bounds them.
      @invariant  reads no cents and knows no ratios — coords/strikes/releases/classes → indices  @ 249
      @contract  strands, n, strength → the index per strand minimising sonority.cost, exactly  @ 250
  @api sonority.springs(members, seat, spelling)  @ 305-319
      -- Each member's pure position is the first's seat plus its coords' cents; a spring's delta
      -- is the difference of the nearest-octave gaps to each seat (design/adaptive-springs.md § The model).
      @contract  members, spelling per member; seat per strand → a Spring per pair, i before j  @ 303
      @contract  springs alone: a spelling's box is sonority.score(spelling), charged where it is chosen  @ 304
  @api sonority.springCost(spellings, displacement, stiffness, from, to)  @ 332-341
      -- What a run of sonorities' springs charge: each spring against the gap its two strands
      -- would sound pure at, the pair standing where the displacements put them.
      @contract  spellings (a sonority.springs list per sonority) and displacement per strand  @ 330
      @contract  from, to → stiffness × (mistuning/50)² per spring of those onsets  @ 331
  @api sonority.pullCost(displacement, window, strength, strands)  @ 347-356
      -- What the pull charges: each strand's displacement over the half-window it lies in.
      @contract  displacement and window per strand, strands: the ones to charge  @ 345
      @contract  → strength × strain² apiece  @ 346
  @api sonority.ties(springs, free, onsets, base)  @ 370-401
      -- Where each spring would stand its two strands, given the other: i a delta below j, j a
      -- delta above i, gathered for the strands that sweep since a held strand reads only its neighbours' ties, pre-summed since they stand still while the sweeps run.
      @contract  springs per onset, the strands that sweep, the onsets to tie (all of them by default)  @ 367
      @contract  base: a Ties to start from, carried whole, over onsets this call does not tie again  @ 368
      @contract  → a Ties: the base's, and what those onsets' springs tie on top of it  @ 369
  @api sonority.relax(ties, window, strength, stiffness, start, free)  @ 420-434
  @api sonority.spellings(members, seat, window, mayWait, moves, width, stiffness)  @ 661-674
      -- A waiting member states no interval, so waiting is a choice the beam makes per member; a
      -- deferral is no rival to a spelling, so the cut runs within a waiting count (§ The candidates).
  @api sonority.seats(strands, notation)  @ 681-689
      -- One window serves a strand in every register, so notes[1] speaks for all of them; the
      -- seat keeps the register it was written in, which tuning.gapTo quotients out again.
      @contract  strands, notation → the cents of each strand's written step, and its window either side  @ 680
  @api sonority.onsets(strands, sonorities)  @ 696-714
      -- A member is free to wait while an onset it sounds through is still to come; at that onset
      -- it places or the state fails (design/adaptive-springs.md § The candidates).
      @contract  strands, sonorities → an Onset per sonority, its members the walk's own  @ 694
      @contract  a member the sonority holds by recency has stopped: it neither sounds nor waits  @ 695
  @api sonority.search(onsets, spellings, seat, window, strength, stiffness, cap)  @ 1028-1071
      -- The cost is taken over every spring accumulated so far rather than the onset's own, so
      -- a spelling is priced against the past it is chosen behind (§ The solve).
  -- The placement
  @api sonority.solveToMoves(strands, n, strength, notation, moves, stiffness)  @ 1083-1102
      -- The moves facility's solve: intervals rather than points, spelled by the beam under a
      -- frozen past, settled by joint relaxation (design/adaptive-springs.md § The solve).
      @contract  strands, n, strength, notation, moves, stiffness → the cents each strand settles at  @ 1081
      @contract  nil where an onset has no spelling — a sonority the target cannot reach refuses it  @ 1082

